+for(let z of [-29,-13])box(scene,-27,.2,z,16,.06,.12,M.white,false);for(let x of [-35,-19])box(scene,x,.2,-21,.12,.06,18,M.white,false);
+function hoop(x,z,dir=1){box(scene,x,.11,z,1.4,.2,1.4,M.black);box(scene,x,1.7,z,.14,3.2,M.white);box(scene,x,3.25,z-dir*.55,1.2,.08,.08,M.white);box(scene,x,3.62,z-dir*.55,1.7,1.15,.12,M.window);cyl(scene,x,3.05,z-dir*1.35,.48,.06,M.hoop,16);const net=new THREE.Mesh(new THREE.CylinderGeometry(.42,.27,.58,12,1,true),new THREE.MeshBasicMaterial({color:0xffffff,wireframe:true}));net.position.set(x,2.76,z-dir*1.35);scene.add(net)}hoop(-27,-30,1);hoop(-27,-12,-1);
+// boxing gym / corner store props
+box(scene,-29,2.7,2,11,5.4,8,M.brick3);box(scene,-29,5.45,2,11.3,.22,8.3,M.roof);box(scene,-29,3.1,-2.08,4.2,1.1,.12,M.orange);box(scene,-29,3.12,-2.17,3.8,.7,.04,M.black);const sign=box(scene,-29,3.12,-2.2,3.5,.32,.04,M.white,false);sign.userData.sign=true;
