+const cars=[];
+function makeCar(x,z,color,label){const group=new THREE.Group();scene.add(group);const bodymat=mat(color,.36,.25);box(group,0,.62,0,2.35,.65,4.3,bodymat);box(group,0,1.15,-.15,1.75,.65,2.15,M.glass);box(group,0,1.48,.93,1.55,.12,.06,M.white,false);for(const xx of [-1.23,1.23])for(const zz of [-1.35,1.35]){const wheel=cyl(group,xx,.38,zz,.42,.25,M.black,16);wheel.rotation.z=Math.PI/2;const hub=cyl(group,xx*1.02,.38,zz,.18,.27,mat(0x9ba59c,.25,.7),12);hub.rotation.z=Math.PI/2}for(const xx of [-.76,.76]){box(group,xx,.72,2.18,.36,.19,.09,M.white,false);box(group,xx,.72,-2.18,.4,.19,.08,M.hoop,false)}group.position.set(x,0,z);group.rotation.y=Math.PI;const data={group,x,z,label,speed:0};cars.push(data);return data}
+makeCar(-5.3,12,0xd9563d,'RED COUPE');makeCar(5.1,-4,0xd5b743,'GOLD SEDAN');makeCar(2,31,0x557c9a,'BLUE HATCHBACK');
