let sideRun=false;const marker=new THREE.Mesh(new THREE.TorusGeometry(1.15,.12,8,24),new THREE.MeshBasicMaterial({color:0xd8ff58}));marker.rotation.x=Math.PI/2;marker.position.set(0,.35,-66);scene.add(marker);const beacon=new THREE.PointLight(0xd8ff58,2,14);beacon.position.set(0,2,-66);scene.add(beacon);$('#startRun').onclick=()=>{sideRun=true;$('#objectiveTag').textContent='SIDE HUSTLE · ACTIVE';$('#objectiveText').innerHTML='Make the drop <em>— follow the green marker</em>';toast('Package secured. Head to the green marker.');closePanels()};
function equip(){playerState.weapon=!playerState.weapon;$('#weaponName').textContent=playerState.weapon?'TRAINING BLASTER':'BARE HANDS';$('#ammo').textContent=playerState.weapon?playerState.ammo+' / 12':'∞';toast(playerState.weapon?'Training blaster equipped. Targets only.':'Training blaster stowed.')}
$$('[data-action="weapon"]').forEach(b=>b.onclick=()=>{equip();closePanels()});let carsCurrentPos=new THREE.Vector3();function toggleCar(car){if(playerState.car){playerState.car=null;player.position.copy(carsCurrentPos);toast('You stepped out.');return}if(car){playerState.car=car;car.speed=0;player.position.copy(car.group.position);carsCurrentPos.copy(player.position);toast(`${car.label} · E to exit`);closePanels()}}
function nearestCar(){let best=null,d=4;for(const c of cars){const n=player.position.distanceTo(c.group.position);if(n<d){best=c;d=n}}return best}$$('[data-action="car"]').forEach(b=>b.onclick=()=>{const c=nearestCar()||cars.slice().sort((a,b)=>a.group.position.distanceTo(player.position)-b.group.position.distanceTo(player.position))[0];if(playerState.car)toggleCar();else if(player.position.distanceTo(c.group.position)<4)toggleCar(c);else toast('Walk up to a parked car to take the wheel.');closePanels()});
let game={active:false,type:'basketball',score:0,round:0,dir:1,pos:0,done:false};function startGame(type){game={active:true,type,score:0,round:0,dir:1,pos:0,done:false};$('#gameTitle').textContent=type==='basketball'?'Free throw challenge':'Boxing spar';$('#gameLabel').textContent=type==='basketball'?'COURT 01 · TIMING':'RING 02 · COMBO';$('#gamePrompt').textContent=type==='basketball'?'Stop the moving needle in the green zone.':'Hit when the needle crosses the green zone.';$('#gameScore').textContent=type==='basketball'?'0 / 3':'0 / 5';$('#gameAction').textContent=type==='basketball'?'SHOOT':'PUNCH';$('#gameAction').onclick=takeGameAction;openPanel('gameplay')}
$$('[data-game]').forEach(b=>b.onclick=()=>startGame(b.dataset.game));$('#gameAction').onclick=takeGameAction;function takeGameAction(){if(!game.active||game.done)return;const sweet=game.type==='basketball'?(game.pos>=.66&&game.pos<=.78):(game.pos>=.44&&game.pos<=.56);if(sweet){game.score++;toast(game.type==='basketball'?'SWISH! Clean bucket.':'CLEAN HIT! Nice combo.')}else toast(game.type==='basketball'?'Off the rim. Try again.':'You missed the rhythm. Reset.');game.round++;$('#gameScore').textContent=`${game.score} / ${game.type==='basketball'?3:5}`;if(game.round>=(game.type==='basketball'?3:5)){game.done=true;game.active=false;if(game.score>=(game.type==='basketball'?2:3)){const reward=game.type==='basketball'?75:90;setCash(reward);setRep(2);$('#gamePrompt').textContent='You got game. Prize claimed!';toast(`Challenge won · $${reward} + 2 REP`)}else $('#gamePrompt').textContent='Good run. Come back and try again.';$('#gameAction').textContent='DONE';$('#gameAction').onclick=()=>{closePanels();$('#gameAction').onclick=takeGameAction}}}
const keys={};let yaw=0,pitch=.12,locked=false;document.addEventListener('keydown',e=>{keys[e.key.toLowerCase()]=true;if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(e.key.toLowerCase()))e.preventDefault();if(e.key==='Tab'){e.preventDefault();openPanel('phone')}if(e.key==='Escape')closePanels();if(e.key.toLowerCase()==='e')interact();if(e.key===' '){if(game.active)takeGameAction();else if(!playerState.car)player.position.y=.12}if(e.key.toLowerCase()==='h')openPanel('controls')});document.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);
renderer.domElement.addEventListener('click',()=>{if(!$$('.panel.open').length){if(playerState.weapon)firePractice();else if(innerWidth>700)renderer.domElement.requestPointerLock?.()}});document.addEventListener('pointerlockchange',()=>locked=document.pointerLockElement===renderer.domElement);document.addEventListener('mousemove',e=>{if(locked){yaw-=e.movementX*.0022;pitch=THREE.MathUtils.clamp(pitch+e.movementY*.0015,-.35,.55)}});
function firePractice(){if(playerState.ammo<=0){toast('Training magazine empty. Visit the gear locker.');return}playerState.ammo--;$('#ammo').textContent=playerState.ammo+' / 12';toast('Practice shot · no damage')}
$$('[data-hold]').forEach(b=>{const k=b.dataset.hold;b.addEventListener('pointerdown',e=>{e.preventDefault();keys[k]=true});['pointerup','pointerleave','pointercancel'].forEach(ev=>b.addEventListener(ev,()=>keys[k]=false))});$$('[data-action="interact"]').forEach(b=>b.onclick=interact);$$('[data-action="jump"]').forEach(b=>b.onclick=()=>player.position.y=.12);
function interact(){if(playerState.car){toggleCar();return}const car=nearestCar();if(car&&player.position.distanceTo(car.group.position)<3.8){toggleCar(car);return}let nearest=null,dist=4;for(const p of interactables){const d=Math.hypot(player.position.x-p.x,player.position.z-p.z);if(d<dist){dist=d;nearest=p}}if(nearest)nearest.action();else toast('Nothing nearby. Explore the block.')}
</body></html>

