const mobileControls={active:false,look:false,stickX:0,stickY:0,sprint:false};
function bindMobileInput(){
 const stick=$('.stick-base'),knob=$('.stick-knob'),lookZone=$('.look-zone');
 const setActive=(el,bool)=>el.classList.toggle('pressed',bool);
 if(stick){
  let pointerId=null;
  const move=e=>{if(e.pointerId!==pointerId)return;mobileControls.stickX=THREE.MathUtils.clamp((e.clientX-mobileControls.startX)/42,-1,1);mobileControls.stickY=THREE.MathUtils.clamp((e.clientY-mobileControls.startY)/42,-1,1);knob.style.transform=`translate(calc(-50% + ${mobileControls.stickX*28}px), calc(-50% + ${mobileControls.stickY*28}px))`;};
  const end=e=>{if(e.pointerId!==pointerId)return;pointerId=null;mobileControls.active=false;mobileControls.stickX=0;mobileControls.stickY=0;knob.style.transform='translate(-50%,-50%)';};
  stick.addEventListener('pointerdown',e=>{if(pointerId!==null)return;e.preventDefault();pointerId=e.pointerId;mobileControls.active=true;mobileControls.startX=e.clientX;mobileControls.startY=e.clientY;stick.setPointerCapture(e.pointerId);move(e);});
  stick.addEventListener('pointermove',move);stick.addEventListener('pointerup',end);stick.addEventListener('pointercancel',end);stick.addEventListener('lostpointercapture',end);
 }
 if(lookZone){
  let pointerId=null,lastX=0,lastY=0;
  const end=e=>{if(e.pointerId!==pointerId)return;pointerId=null;mobileControls.look=false;};
  lookZone.addEventListener('pointerdown',e=>{if(pointerId!==null)return;e.preventDefault();pointerId=e.pointerId;lastX=e.clientX;lastY=e.clientY;mobileControls.look=true;lookZone.setPointerCapture(e.pointerId);});
  lookZone.addEventListener('pointermove',e=>{if(e.pointerId!==pointerId)return;const dx=e.clientX-lastX,dy=e.clientY-lastY;lastX=e.clientX;lastY=e.clientY;yaw-=dx*.0035;pitch=THREE.MathUtils.clamp(pitch+dy*.0023,-.35,.55);});
  lookZone.addEventListener('pointerup',end);lookZone.addEventListener('pointercancel',end);lookZone.addEventListener('lostpointercapture',end);
 }
 $$('[data-mobile]').forEach(btn=>{
  let pointerId=null;
  const release=e=>{if(e&&e.pointerId!==pointerId)return;pointerId=null;setActive(btn,false);if(btn.dataset.mobile==='sprint')mobileControls.sprint=false;};
  btn.addEventListener('pointerdown',e=>{if(pointerId!==null)return;e.preventDefault();pointerId=e.pointerId;btn.setPointerCapture(e.pointerId);setActive(btn,true);const action=btn.dataset.mobile;if(action==='jump'){if(game.active)takeGameAction();else if(!playerState.car)player.position.y=.12}else if(action==='action')interact();else if(action==='phone')openPanel('phone');else if(action==='sprint')mobileControls.sprint=true;});
  btn.addEventListener('pointerup',release);btn.addEventListener('pointercancel',release);btn.addEventListener('lostpointercapture',release);
 });
}

