@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=Space+Grotesk:wght@400;500;600;700&display=swap');
:root{--ink:#f4f1e8;--muted:#a3a99f;--lime:#d8ff58;--panel:rgba(13,20,20,.88);--line:rgba(240,245,226,.14);--orange:#ff875e}
*{box-sizing:border-box}
html,body{margin:0;width:100%;height:100%;overflow:hidden;background:#101919;color:var(--ink);font-family:'Space Grotesk',sans-serif}
canvas{display:block}
#world{position:fixed;inset:0}
#hud{position:fixed;inset:0;pointer-events:none}
.topbar{position:absolute;left:28px;right:28px;top:24px;display:flex;align-items:flex-start;justify-content:space-between}
.brand{display:flex;gap:12px;align-items:center}
.brandmark{width:38px;height:38px;border:1px solid var(--lime);color:var(--lime);display:grid;place-items:center;font-size:19px;font-weight:700;transform:rotate(-4deg)}
.brandname{font-size:12px;letter-spacing:.18em;font-weight:700}
.brandname small{display:block;color:var(--muted);font:10px 'DM Mono';letter-spacing:.13em;margin-top:3px}
.topright{display:flex;gap:10px}
.pill{background:rgba(11,17,17,.75);border:1px solid var(--line);padding:10px 14px;border-radius:4px;font:11px 'DM Mono';letter-spacing:.06em}
.pill span{color:var(--lime)}
.mapbox{position:absolute;right:28px;top:84px;width:180px;height:150px;border:1px solid var(--line);background:rgba(9,18,18,.76);overflow:hidden}
.maptitle{position:absolute;z-index:2;left:10px;top:8px;font:9px 'DM Mono';letter-spacing:.18em;color:#d4dfcb}
.mapbox canvas{width:100%;height:100%}
.mapdot{position:absolute;left:50%;top:50%;width:7px;height:7px;border-radius:100%;background:var(--lime);box-shadow:0 0 12px var(--lime)}
.location{position:absolute;left:28px;bottom:32px}
.loc-kicker{font:10px 'DM Mono';letter-spacing:.2em;color:var(--lime)}
.loc-title{font-size:30px;font-weight:700;letter-spacing:-.04em;margin-top:5px}
.loc-sub{font:10px 'DM Mono';color:var(--muted);margin-top:5px}
.objective{position:absolute;left:28px;top:105px;border-left:2px solid var(--lime);padding:4px 0 4px 12px}
.objective small{font:9px 'DM Mono';color:var(--lime);letter-spacing:.16em}
.objective div{font-size:13px;font-weight:600;margin-top:5px}
.objective em{font-style:normal;color:var(--muted);font-size:11px;font-weight:400}
.toast{position:absolute;left:50%;top:20%;transform:translate(-50%,-10px);background:#101a18;border:1px solid #d8ff58;color:white;padding:11px 18px;font-size:12px;opacity:0;transition:.3s;white-space:nowrap}
.toast.show{opacity:1;transform:translate(-50%,0)}
.hint{position:absolute;left:50%;bottom:35px;transform:translateX(-50%);background:rgba(8,14,14,.77);border:1px solid var(--line);padding:10px 15px;border-radius:4px;font:10px 'DM Mono';color:#d2d8cd;white-space:nowrap}
.key{display:inline-grid;place-items:center;border:1px solid #607068;border-radius:3px;padding:2px 5px;color:var(--lime);margin:0 3px}
.health{position:absolute;left:28px;bottom:115px;width:175px}
.health-label{font:9px 'DM Mono';color:var(--muted);letter-spacing:.12em;display:flex;justify-content:space-between;margin-bottom:7px}
.bar{height:4px;background:#37413b}
.bar i{display:block;width:100%;height:100%;background:var(--lime)}
.weapon{position:absolute;right:28px;bottom:32px;text-align:right}
.weapon-label{font:9px 'DM Mono';letter-spacing:.14em;color:var(--muted)}
.weapon-name{font-size:16px;font-weight:600;margin-top:4px}
.ammo{font:11px 'DM Mono';color:var(--lime);margin-top:3px}
.crosshair{position:absolute;left:50%;top:50%;width:14px;height:14px;transform:translate(-50%,-50%);opacity:.8}
.crosshair:before,.crosshair:after{content:'';position:absolute;background:#fff}
.crosshair:before{left:6px;top:0;width:1px;height:14px}
.crosshair:after{top:6px;left:0;height:1px;width:14px}
.panel{position:absolute;left:50%;top:50%;transform:translate(-50%,-50%);width:min(560px,calc(100vw - 32px));max-height:85vh;overflow:auto;background:var(--panel);border:1px solid var(--line);box-shadow:0 25px 100px #000b;padding:24px;pointer-events:auto;display:none;backdrop-filter:blur(16px)}
.panel.open{display:block}
.panelhead{display:flex;justify-content:space-between;align-items:flex-start;border-bottom:1px solid var(--line);padding-bottom:16px;margin-bottom:18px}
.eyebrow{font:9px 'DM Mono';letter-spacing:.2em;color:var(--lime)}
h2{font-size:25px;line-height:1;margin:7px 0 0;letter-spacing:-.04em}
.close{background:none;border:1px solid var(--line);color:white;padding:6px 9px;cursor:pointer;font:11px 'DM Mono'}
.panel p{font-size:12px;color:#aab3a9;line-height:1.55}
.cards{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.card{border:1px solid var(--line);padding:14px;background:#ffffff06}
.card h3{margin:0 0 5px;font-size:14px}
.card p{margin:0 0 12px;font-size:11px}
.card button,.action{border:0;background:var(--lime);color:#15200f;padding:9px 12px;font:700 10px 'DM Mono';letter-spacing:.08em;cursor:pointer}
.card button:hover,.action:hover{background:#efffb0}
.card .reward{font:10px 'DM Mono';color:var(--lime);margin-bottom:10px}
.row{display:flex;align-items:center;justify-content:space-between;border-top:1px solid var(--line);padding:12px 0;font-size:12px}
.row select{background:#1b2824;color:white;border:1px solid #45534b;padding:7px;font:11px 'DM Mono'}
.swatches{display:flex;gap:8px}
.swatch{width:22px;height:22px;border-radius:50%;border:2px solid transparent;cursor:pointer}
.swatch.active{outline:2px solid var(--lime);outline-offset:2px}
.hintpanel{display:grid;grid-template-columns:1fr 1fr;gap:10px}
.hintpanel div{font:11px 'DM Mono';color:#bdc8be}
.hintpanel b{color:var(--lime);display:inline-block;width:70px}
.minigame{font-size:13px;text-align:center;padding:20px}
.meter{height:16px;border:1px solid var(--line);position:relative;margin:25px auto;width:80%;background:#151f1c}
.meter .sweet{position:absolute;left:66%;width:12%;height:100%;background:#d8ff583b;border-left:1px solid var(--lime);border-right:1px solid var(--lime)}
.meter .needle{position:absolute;left:0;height:100%;width:3px;background:white}
.gamebig{font-size:31px;color:var(--lime);font-weight:700;margin:18px}
.mobile-controls{display:none;position:absolute;inset:0;pointer-events:none;touch-action:none;z-index:5}
.mobile-controls button{width:58px;height:58px;border:1px solid #ffffff70;background:rgba(7,16,12,.72);color:white;border-radius:50%;font:10px 'DM Mono';touch-action:none;pointer-events:auto;box-shadow:0 4px 18px #0006;backdrop-filter:blur(5px);user-select:none;-webkit-user-select:none}
.mobile-controls button:active,.mobile-controls button.pressed{background:#d8ff5844;border-color:var(--lime)}
.stick-base{position:absolute;left:max(18px,env(safe-area-inset-left));bottom:calc(22px + env(safe-area-inset-bottom));width:142px;height:142px;border:1px solid #ffffff60;border-radius:50%;background:#07100c55;pointer-events:auto;touch-action:none;backdrop-filter:blur(3px)}
.stick-base:after{content:'MOVE';position:absolute;inset:0;display:grid;place-items:center;color:#ffffff78;font:9px 'DM Mono';letter-spacing:.16em;pointer-events:none}
.stick-knob{position:absolute;left:50%;top:50%;width:58px;height:58px;border-radius:50%;transform:translate(-50%,-50%);background:#d8ff5866;border:1px solid var(--lime);box-shadow:0 0 18px #d8ff5830;pointer-events:none}
.look-zone{position:absolute;top:15%;right:0;width:54%;height:65%;pointer-events:auto;touch-action:none}
.mobile-actions{position:absolute;right:max(18px,env(safe-area-inset-right));bottom:calc(20px + env(safe-area-inset-bottom));display:flex;align-items:end;gap:10px;pointer-events:none}
.mobile-actions .small-action{width:48px;height:48px}
.mobile-actions .primary-action{width:68px;height:68px;border-color:var(--lime);color:var(--lime)}
.mobile-actions .action-stack{display:flex;flex-direction:column;gap:8px}
.mobile-actions .phone-action{position:absolute;right:0;bottom:162px;width:46px;height:46px}
.touch-help{position:absolute;right:18px;bottom:calc(98px + env(safe-area-inset-bottom));font:8px 'DM Mono';letter-spacing:.1em;color:#ffffffa8;text-shadow:0 1px 5px #000}
.mobile-controls .look-zone{z-index:0}
.mobile-controls .stick-base,.mobile-controls .mobile-actions{z-index:1}
.sound{position:absolute;right:28px;top:245px;font:9px 'DM Mono';color:#a6b0a7;letter-spacing:.08em}
.hidden{display:none!important}
@media(max-width:700px){.topbar{left:14px;right:14px;top:max(12px,env(safe-area-inset-top))}
.mapbox{top:75px;right:14px;width:132px;height:110px}
.objective{top:78px;left:14px;max-width:170px}
.objective div{font-size:11px}
.location{left:14px;bottom:calc(168px + env(safe-area-inset-bottom))}
.loc-title{font-size:22px}
.loc-sub{font-size:8px}
.health{left:14px;top:205px;bottom:auto;width:130px}
.weapon{right:14px;top:198px;bottom:auto}
.hint{display:none}
.sound{display:none}
.mobile-controls{display:flex}
.pill{padding:8px 9px;font-size:9px}
.brandname{font-size:10px}
.brandmark{width:32px;height:32px}
.cards{grid-template-columns:1fr}
.panel{padding:18px}
.topright{gap:5px}
.mobile-controls button{min-width:46px;min-height:46px}
.touch-help{right:20px;bottom:calc(104px + env(safe-area-inset-bottom))}
}
@media(max-width:380px){.brandname small{font-size:8px}
.mapbox{width:112px;height:94px}
.objective{max-width:145px}
.mobile-actions{right:max(12px,env(safe-area-inset-right));gap:7px}
.stick-base{width:126px;height:126px;left:max(12px,env(safe-area-inset-left));bottom:calc(18px + env(safe-area-inset-bottom))}
.mobile-actions .primary-action{width:60px;height:60px}
.mobile-actions .small-action{width:44px;height:44px}
.mobile-actions .phone-action{bottom:150px}
}
@media (orientation:landscape) and (max-height:500px){.topbar{top:8px}
.mapbox{top:58px;width:110px;height:82px}
.objective{top:58px}
.health{top:150px}
.weapon{top:150px}
.location{bottom:calc(12px + env(safe-area-inset-bottom))}
.stick-base{width:112px;height:112px;bottom:calc(10px + env(safe-area-inset-bottom))}
.mobile-actions{bottom:calc(10px + env(safe-area-inset-bottom))}
.mobile-actions .phone-action{bottom:120px}
.look-zone{top:12%;height:72%}
.touch-help{display:none}
}

