node --input-type=module - <<'NODE'
import {createRequire} from 'node:module';import {readFileSync} from 'node:fs';const require=createRequire(process.env.HOME+'/.local/share/omgithub-playwright/package.json');const {chromium}=require('playwright');if(process.platform==='linux'&&!process.env.DISPLAY)process.env.DISPLAY=':'+readFileSync(process.env.HOME+'/.local/share/omgithub-playwright/display','utf8').trim();const c=require(process.env.HOME+'/.local/share/omgithub-playwright/linux.json');const browser=await chromium.launch({...c.browser.launchOptions});const page=await browser.newPage({viewport:{width:390,height:844},deviceScaleFactor:1,isMobile:true,hasTouch:true});const errors=[];page.on('pageerror',e=>errors.push(e.message));await page.goto('http://localhost:3002/',{waitUntil:'networkidle'});await page.waitForTimeout(1000);
const results=[];for(const [name,selector] of [['sprint','[data-mobile="sprint"]'],['jump','[data-mobile="jump"]'],['action','[data-mobile="action"]'],['phone','[data-mobile="phone"]']]){const r=page.locator(selector),b=await r.boundingBox();await page.mouse.move(b.x+b.width/2,b.y+b.height/2);await page.mouse.down();await page.waitForTimeout(90);const pressed=await r.evaluate(e=>e.classList.contains('pressed'));await page.mouse.up();await page.waitForTimeout(100);const released=await r.evaluate(e=>!e.classList.contains('pressed'));results.push({name,pressed,released})}
const phone=page.locator('#phone');for(const [name,button,expect] of [['jobs','[data-open="jobs"]','#jobs'],['customize','[data-open="customize"]','#customize'],['games','[data-open="minigames"]','#minigames'],['hustle','[data-open="hustle"]','#hustle']]){if(!await phone.evaluate(e=>e.classList.contains('open'))){const b=await page.locator('[data-mobile="phone"]').boundingBox();await page.touchscreen.tap(b.x+b.width/2,b.y+b.height/2)}await page.locator(button).click();const open=await page.locator(expect).evaluate(e=>e.classList.contains('open'));results.push({panel:name,open});await page.locator(`${expect} [data-close]`).click()}
await page.screenshot({path:'/tmp/opencode/current/final-mobile.png'});console.log(JSON.stringify({results,errors}));await browser.close();
